script:
// ---- full page width -------------------------------------------------
// Removes the workspace's max-width so the dashboard fills the screen,
// and puts it back when you navigate to any other page.
(function () {
  var W = (window.__tbhSD = window.__tbhSD || { saved: [], hooked: false });
  function onPage() { return /\/solar-dashboard\/?$/i.test(location.pathname); }
  function restore() { W.saved.forEach(function (p) { p[0].style.maxWidth = p[1]; }); W.saved = []; }
  function widen() {
    restore();
    if (!onPage()) { return; }
    var rn = root_element.getRootNode ? root_element.getRootNode() : null;
    var el = (rn && rn.host) || root_element;
    while (el && el !== document.body && el !== document.documentElement) {
      var mw = getComputedStyle(el).maxWidth;
      if (mw && mw !== 'none') { W.saved.push([el, el.style.maxWidth]); el.style.maxWidth = 'none'; }
      el = el.parentElement;
    }
  }
  W.apply = widen;
  if (!W.hooked && frappe.router && typeof frappe.router.on === 'function') {
    W.hooked = true;
    frappe.router.on('change', function () { setTimeout(function () { if (W.apply) { W.apply(); } }, 60); });
  }
  widen();
  setTimeout(widen, 300);
})();

// Fixed rows: core doctypes whose status lists are too long to show in full.
const FIXED = [
  { title: 'Leads', dt: 'CRM Lead', color: '#2563eb', rows: [
    { label: 'New', f: { status: 'New' } },
    { label: 'Contacted', f: { status: 'Contacted' } },
    { label: 'Qualified', f: { status: 'Qualified' } },
    { label: 'Converted', f: { status: 'Converted' } }
  ]},
  { title: 'Quotation', dt: 'Quotation', color: '#7c3aed', rows: [
    { label: 'Draft', f: { status: 'Draft' } },
    { label: 'Open', f: { status: 'Open' } },
    { label: 'Ordered', f: { status: 'Ordered' } },
    { label: 'Lost', f: { status: 'Lost' } }
  ]},
  { title: 'Sales Order', dt: 'Sales Order', color: '#0891b2', rows: [
    { label: 'To Deliver and Bill', f: { status: 'To Deliver and Bill' } },
    { label: 'To Deliver', f: { status: 'To Deliver' } },
    { label: 'To Bill', f: { status: 'To Bill' } },
    { label: 'Completed', f: { status: 'Completed' } }
  ]},
  { title: 'Sales Invoice', dt: 'Sales Invoice', color: '#059669', rows: [
    { label: 'Draft', f: { status: 'Draft' } },
    { label: 'Unpaid', f: { status: 'Unpaid' } },
    { label: 'Overdue', f: { status: 'Overdue' } },
    { label: 'Paid', f: { status: 'Paid' } },
    { label: 'Return', f: { status: 'Return' } }
  ]}
];

const AUTO = [
  { title: 'Loan',               dt: 'Solar Loan',         field: 'status',                     color: '#4f46e5' },
  { title: 'Site Visit',         dt: 'Site Visit',         field: 'status',                     color: '#0d9488' },
  { title: 'Project',            dt: 'Project',            field: 'status',                     color: '#db2777' },
  { title: 'Product Delivery',   dt: 'Product Delivery',   field: 'transfer_status',            color: '#ea580c' },
  { title: 'Installation',       dt: 'Installation',       field: 'installation_status',        color: '#16a34a' },
  { title: 'Paper Work',         dt: 'Paper Work',         field: 'status',                     color: '#0284c7' },
  { title: 'Subsidy',            dt: 'Subsidy',            field: 'status',                     color: '#d97706' },
  { title: 'KSEB',               dt: 'KSEB Paper Works',   field: 'status_of_kseb_paper_work',  color: '#0f766e' },
  { title: 'Project Commission', dt: 'Project Commission', field: 'status_of_project_commission', color: '#9333ea' }
];

const TREND = [
  { name: 'Lead',          dt: 'CRM Lead',      datefield: 'creation',         color: '#2563eb' },
  { name: 'Quotation',     dt: 'Quotation',     datefield: 'transaction_date', color: '#7c3aed' },
  { name: 'Sales Order',   dt: 'Sales Order',   datefield: 'transaction_date', color: '#0891b2' },
  { name: 'Sales Invoice', dt: 'Sales Invoice', datefield: 'posting_date',     color: '#059669' }
];

const MONTHS_BACK = 12;
const GL_ROW_CAP = 20000;

const grid = root_element.querySelector('.sd-grid');
const chartBox = root_element.querySelector('.sd-chart');
const plBox = root_element.querySelector('.sd-chart-pl');

function tone_for(label) {
  const l = String(label).toLowerCase();
  if (l.indexOf('cancel') > -1 || l.indexOf('lost') > -1 || l.indexOf('reject') > -1 || l.indexOf('fail') > -1 || l.indexOf('overdue') > -1) { return 'bad'; }
  if (l.indexOf('complet') > -1 || l.indexOf('approv') > -1 || l.indexOf('sanction') > -1 || l.indexOf('transferr') > -1 || l.indexOf('visited') > -1 || l.indexOf('commission') > -1 || l.indexOf('disburs') > -1 || l.indexOf('paid') > -1) { return 'good'; }
  if (l.indexOf('progress') > -1 || l.indexOf('process') > -1 || l.indexOf('review') > -1 || l.indexOf('submit') > -1) { return 'info'; }
  if (l.indexOf('pending') > -1 || l.indexOf('not ') > -1 || l.indexOf('applied') > -1 || l.indexOf('hold') > -1 || l.indexOf('unpaid') > -1) { return 'warn'; }
  return 'idle';
}

function count(dt, filters) {
  return frappe.db.count(dt, filters ? { filters: filters } : undefined)
    .then(function(v) { return v || 0; })
    .catch(function() { return 0; });
}

function status_options(dt, fieldname) {
  return new Promise(function(resolve) {
    frappe.model.with_doctype(dt, function() {
      var df = null;
      try { df = frappe.meta.get_docfield(dt, fieldname); } catch (e) { df = null; }
      if (!df || !df.options) { resolve([]); return; }
      resolve(String(df.options).split('\n').map(function(s) { return s.trim(); }).filter(function(s) { return s.length; }));
    });
  });
}

function shell(card, container) {
  const el = document.createElement('div');
  el.className = 'sd-card';
  el.style.setProperty('--accent', card.color);
  el.innerHTML = '<div class="sd-card-head">' + card.title + '</div>' +
    '<div class="sd-rows"></div>' +
    '<div class="sd-total"><span>Total</span><span class="sd-tval">–</span></div>';
  container.appendChild(el);
  return el;
}

function paint_rows(el, card, rows) {
  const holder = el.querySelector('.sd-rows');
  if (!rows.length) {
    holder.innerHTML = '<div class="sd-empty">No status options found</div>';
  } else {
    holder.innerHTML = rows.map(function(r, i) {
      return '<div class="sd-row" data-i="' + i + '">' +
             '<span class="sd-dot sd-dot-' + tone_for(r.label) + '"></span>' +
             '<span class="sd-label">' + r.label + '</span>' +
             '<span class="sd-val">–</span></div>';
    }).join('');
    const rowEls = holder.querySelectorAll('.sd-row');
    rows.forEach(function(r, i) {
      rowEls[i].addEventListener('click', function() { frappe.set_route('List', card.dt, r.f); });
      count(card.dt, r.f).then(function(v) {
        rowEls[i].querySelector('.sd-val').textContent = v;
        if (!v) { rowEls[i].classList.add('sd-zero'); }
      });
    });
  }
  el.querySelector('.sd-total').addEventListener('click', function() { frappe.set_route('List', card.dt); });
  count(card.dt).then(function(v) { el.querySelector('.sd-tval').textContent = v; });
}

FIXED.forEach(function(card) {
  paint_rows(shell(card, grid), card, card.rows);
});

AUTO.forEach(function(card) {
  const el = shell(card, grid);
  el.querySelector('.sd-rows').innerHTML = '<div class="sd-empty">Loading…</div>';
  status_options(card.dt, card.field).then(function(opts) {
    paint_rows(el, card, opts.map(function(o) {
      var f = {}; f[card.field] = o;
      return { label: o, f: f };
    }));
  });
});

// ---- shared month axis ------------------------------------------------
// Rows are fetched as plain values and bucketed by month in the browser.
// Grouping with SQL date functions is rejected by Frappe field validation,
// so this stays on a path that is always permitted.

function month_axis(n) {
  var keys = [], labels = [];
  var now = new Date();
  for (var i = n - 1; i >= 0; i--) {
    var t = new Date(now.getFullYear(), now.getMonth() - i, 1);
    keys.push(t.getFullYear() + '-' + ('0' + (t.getMonth() + 1)).slice(-2));
    labels.push(t.toLocaleString('en', { month: 'short' }) + ' ' + String(t.getFullYear()).slice(-2));
  }
  return { keys: keys, labels: labels };
}

const AXIS = month_axis(MONTHS_BACK);
const START = AXIS.keys[0] + '-01';

function month_series(cfg) {
  var filters = {};
  filters[cfg.datefield] = ['>=', START];

  return frappe.db.get_list(cfg.dt, {
    fields: [cfg.datefield],
    filters: filters,
    order_by: cfg.datefield + ' asc',
    limit: 5000
  }).then(function(rows) {
    var buckets = {};
    AXIS.keys.forEach(function(k) { buckets[k] = 0; });
    (rows || []).forEach(function(r) {
      var v = r[cfg.datefield];
      if (!v) { return; }
      var k = String(v).slice(0, 7);
      if (buckets[k] !== undefined) { buckets[k] += 1; }
    });
    return AXIS.keys.map(function(k) { return buckets[k]; });
  }).catch(function() {
    return AXIS.keys.map(function() { return 0; });
  });
}

function draw_trend() {
  if (typeof frappe.Chart === 'undefined') {
    chartBox.innerHTML = '<div class="sd-chart-empty">Chart library not available on this page.</div>';
    return;
  }

  chartBox.innerHTML = '<div class="sd-chart-empty">Loading trend…</div>';

  Promise.all(TREND.map(month_series)).then(function(all) {
    var grand = all.reduce(function(a, s) {
      return a + s.reduce(function(x, y) { return x + y; }, 0);
    }, 0);

    if (!grand) {
      chartBox.innerHTML = '<div class="sd-chart-empty">No documents in the last ' + MONTHS_BACK + ' months.</div>';
      return;
    }

    chartBox.innerHTML = '';
    new frappe.Chart(chartBox, {
      type: 'bar',
      height: 290,
      colors: TREND.map(function(t) { return t.color; }),
      data: {
        labels: AXIS.labels,
        datasets: TREND.map(function(t, i) {
          return { name: t.name, values: all[i] };
        })
      },
      barOptions: { spaceRatio: 0.4 },
      axisOptions: { xIsSeries: 1 }
    });
  }).catch(function() {
    chartBox.innerHTML = '<div class="sd-chart-empty">Could not load the trend data.</div>';
  });
}

// ---- profit and loss --------------------------------------------------
// Income and expense are summed from posted GL Entries so the figures match
// the ledger rather than being inferred from invoice totals. Root type lives
// on Account, not GL Entry, so the income and expense accounts are resolved
// first and used as a filter.
//
// All three series are bars. shortenYAxisNumbers keeps large rupee figures
// readable on the axis instead of printing every digit.

function draw_pl() {
  if (typeof frappe.Chart === 'undefined') {
    plBox.innerHTML = '<div class="sd-chart-empty">Chart library not available on this page.</div>';
    return;
  }

  plBox.innerHTML = '<div class="sd-chart-empty">Loading profit and loss…</div>';

  frappe.db.get_list('Account', {
    fields: ['name', 'root_type'],
    filters: { root_type: ['in', ['Income', 'Expense']] },
    limit: 1000
  }).then(function(accounts) {
    if (!accounts || !accounts.length) {
      plBox.innerHTML = '<div class="sd-chart-empty">No income or expense accounts found.</div>';
      return;
    }

    var type_of = {};
    var names = [];
    accounts.forEach(function(a) { type_of[a.name] = a.root_type; names.push(a.name); });

    return frappe.db.get_list('GL Entry', {
      fields: ['posting_date', 'account', 'debit', 'credit'],
      filters: {
        posting_date: ['>=', START],
        is_cancelled: 0,
        account: ['in', names]
      },
      order_by: 'posting_date asc',
      limit: GL_ROW_CAP
    }).then(function(rows) {
      var inc = {}, exp = {};
      AXIS.keys.forEach(function(k) { inc[k] = 0; exp[k] = 0; });

      (rows || []).forEach(function(g) {
        var k = String(g.posting_date || '').slice(0, 7);
        if (inc[k] === undefined) { return; }
        var t = type_of[g.account];
        if (t === 'Income') {
          inc[k] += flt(g.credit) - flt(g.debit);
        } else if (t === 'Expense') {
          exp[k] += flt(g.debit) - flt(g.credit);
        }
      });

      var income  = AXIS.keys.map(function(k) { return Math.round(inc[k]); });
      var expense = AXIS.keys.map(function(k) { return Math.round(exp[k]); });
      var profit  = AXIS.keys.map(function(k) { return Math.round(inc[k] - exp[k]); });

      var any = income.concat(expense).some(function(v) { return v !== 0; });
      if (!any) {
        plBox.innerHTML = '<div class="sd-chart-empty">No posted income or expense in the last ' + MONTHS_BACK + ' months.</div>';
        return;
      }

      plBox.innerHTML = '';
      new frappe.Chart(plBox, {
        type: 'bar',
        height: 290,
        colors: ['#16a34a', '#dc2626', '#2563eb'],
        data: {
          labels: AXIS.labels,
          datasets: [
            { name: 'Income', values: income },
            { name: 'Expense', values: expense },
            { name: 'Net Profit', values: profit }
          ]
        },
        barOptions: { spaceRatio: 0.4 },
        axisOptions: { xIsSeries: 1, shortenYAxisNumbers: 1 }
      });
    });
  }).catch(function() {
    plBox.innerHTML = '<div class="sd-chart-empty">Could not load ledger data. This needs read access to Account and GL Entry.</div>';
  });
}

draw_trend();
draw_pl();

style:
:host { display: block; }
.sd-wrap { padding: 2px 0 8px; width: 100%; }
.sd-head { margin-bottom: 18px; }
.sd-title { font-size: 21px; font-weight: 600; letter-spacing: -0.01em; }
.sd-sub { font-size: 12px; color: var(--text-muted, #6b7280); margin-top: 3px; }

.sd-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(255px, 1fr)); gap: 14px; }

.sd-card { background: var(--card-bg, #fff); border: 1px solid var(--border-color, #e5e7eb); border-radius: 12px; padding: 15px 16px 12px; display: flex; flex-direction: column; position: relative; overflow: hidden; }
.sd-card::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px; background: var(--accent); }

.sd-card-head { font-size: 14px; font-weight: 600; color: var(--accent); margin-bottom: 12px; }

.sd-rows { flex: 1; }
.sd-row { display: flex; align-items: center; gap: 8px; padding: 6px 6px; margin: 0 -6px; font-size: 13px; cursor: pointer; border-radius: 6px; transition: background 0.12s ease; }
.sd-row:hover { background: var(--fg-hover-color, #f3f4f6); }
.sd-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--accent); flex: none; }
.sd-dot-good { background: #16a34a; }
.sd-dot-warn { background: #ea580c; }
.sd-dot-info { background: #2563eb; }
.sd-dot-bad { background: #dc2626; }
.sd-dot-idle { background: #9ca3af; }
.sd-label { color: var(--text-color, #374151); flex: 1; }
.sd-val { font-weight: 600; font-variant-numeric: tabular-nums; }
.sd-zero .sd-label, .sd-zero .sd-val { color: var(--text-muted, #9ca3af); }
.sd-zero .sd-dot { opacity: 0.35; }
.sd-empty { font-size: 12px; color: var(--text-muted, #9ca3af); padding: 6px 0; }

.sd-total { display: flex; justify-content: space-between; align-items: baseline; margin-top: 10px; padding-top: 10px; border-top: 1px solid var(--border-color, #e5e7eb); font-size: 12px; font-weight: 600; color: var(--text-muted, #6b7280); cursor: pointer; }
.sd-tval { font-size: 19px; font-weight: 700; color: var(--accent); font-variant-numeric: tabular-nums; }

/* section break */
.sd-divider { height: 1px; background: var(--border-color, #e5e7eb); margin: 28px 0 18px; }
.sd-section-head { font-size: 16px; font-weight: 600; letter-spacing: -0.01em; }
.sd-section-sub { font-size: 12px; color: var(--text-muted, #6b7280); margin-top: 3px; margin-bottom: 14px; }

/* trend chart */
.sd-chart-card { --accent: #2563eb; padding: 6px 10px 2px; }
.sd-chart-empty { font-size: 12px; color: var(--text-muted, #9ca3af); padding: 28px 6px; text-align: center; }
.sd-chart .chart-legend { font-size: 12px; }
